{"command":"python3 << 'EOF'
import csv

# Verify RFC 4180 compliance
with open('outputs/t08_pois_clean.csv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f)
    rows = list(reader)

header = rows[0]
print(f"Header: {header}")
print(f"Header length: {len(header)}")

all_correct = True
for i, row in enumerate(rows[1:], 1):
    if len(row) != 6:
        print(f"Row {i+1} has {len(row)} fields: {row}")
        all_correct = False

if all_correct:
    print(f"All {len(rows)-1} data rows have exactly 6 fields")

# Check that source is 'wikidata' for all rows
for i, row in enumerate(rows[1:], 1):
    if row[5] != 'wikidata':
        print(f"Row {i+1} has source '{row[5]}' instead of 'wikidata'")

# Check all labels are non-empty
for i, row in enumerate(rows[1:], 1):
    if not row[1]:
        print(f"Row {i+1} has empty label")

# Check latitude and longitude are valid
for i, row in enumerate(rows[1:], 1):
    lat = float(row[3])
    lon = float(row[4])
    if not (-90 <= lat <= 90):
        print(f"Row {i+1}: latitude {lat} out of range")
    if not (-180 <= lon <= 180):
        print(f"Row {i+1}: longitude {lon} out of range")

print("Verification complete!")
EOF"}
